// The layout map: closed names, grammars, enums, limits, error codes, and the defaults.
// layout-map.json is a copy of docs/contracts/layout/v1/layout-map.json, generated by
// scripts/layout-contract.ts; a test keeps the copies identical.
import map from "./layout-map.json" with { type: "json" };

export type LayoutMap = {
  contractVersion: number;
  limits: {
    maxBytes: number;
    maxDepth: number;
    urlLength: number;
    uspItems: number;
    uspItemLength: number;
    ctaTextLength: number;
    contactLength: number;
    copyrightLength: number;
    socialItems: number;
    columnsMin: number;
    columnsMax: number;
  };
  grammars: { slug: string; url: string; urlHttps: string };
  enums: { layout: string[]; logo: string[]; mobileMenu: string[]; service: string[] };
  placeholders: string[];
  errorCodes: string[];
  defaults: Record<string, unknown>;
};

export const layoutMap = map as LayoutMap;
